import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        String s = br.readLine();
        int[] a = new int[n];
        int[] cnt = new int[26];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(st.nextToken());
            cnt[s.charAt(i) - 'a']++;
        }
        int pairCount = (n + 1) / 2;
        int V = n + 26 + 2;
        int source = V - 2;
        int sink = V - 1;
        Graph g = new Graph(V);
        for (int i = 0; i < 26; i++) {
            g.addFlowWeightedEdge(source, i + n, 0, cnt[i]);
        }
        for (int i = 0; i < 26; i++) {
            for (int j = 0; j < pairCount; j++) {
                int left = j;
                int right = n - 1 - j;
                long w = 0;
                if (s.charAt(left) == s.charAt(right)) {
                    if (s.charAt(left) == (char)('a' + i)) {
                        w = -Math.max(a[left], a[right]);
                    }
                } else {
                    if (s.charAt(left) == (char)('a' + i)) w -= a[left];
                    if (s.charAt(right) == (char)('a' + i)) w -= a[right];
                }
                g.addFlowWeightedEdge(i + n, j, w, 1);
            }
        }
        for (int j = 0; j < pairCount; j++) {
            g.addFlowWeightedEdge(j, sink, 0, 2);
        }
        MinCostFlow mcmf = new MinCostFlow(g, source, sink, true);
        long cost = mcmf.minCostMaxFlow().first;
        System.out.println(-cost);
    }

    static class Graph {
        int V;
        List<Edge>[] adj;
        Graph(int V) {
            this.V = V;
            adj = new List[V];
            for (int i = 0; i < V; i++) adj[i] = new ArrayList<>();
        }
        void addFlowWeightedEdge(int from, int to, long weight, long capacity) {
            Edge a = new Edge(to, weight, capacity);
            Edge b = new Edge(from, -weight, 0);
            a.rev = b;
            b.rev = a;
            adj[from].add(a);
            adj[to].add(b);
        }
    }

    static class Edge {
        int to;
        long cost, cap;
        Edge rev;
        Edge(int to, long cost, long cap) {
            this.to = to;
            this.cost = cost;
            this.cap = cap;
        }
    }

    static class MinCostFlow {
        Graph g;
        int s, t;
        long[] potential;
        long[] dist;
        int[] prevv, preve;
        MinCostFlow(Graph g, int s, int t, boolean hasNegative) {
            this.g = g;
            this.s = s;
            this.t = t;
            potential = new long[g.V];
            if (hasNegative) {
                // Bellman-Ford
                Arrays.fill(potential, Long.MAX_VALUE);
                potential[s] = 0;
                boolean updated;
                for (int i = 0; i < g.V; i++) {
                    updated = false;
                    for (int v = 0; v < g.V; v++) {
                        if (potential[v] == Long.MAX_VALUE) continue;
                        for (Edge e : g.adj[v]) {
                            if (e.cap > 0 && potential[e.to] > potential[v] + e.cost) {
                                potential[e.to] = potential[v] + e.cost;
                                updated = true;
                            }
                        }
                    }
                    if (!updated) break;
                }
            }
            dist = new long[g.V];
            prevv = new int[g.V];
            preve = new int[g.V];
        }
        Pair<Long, Long> minCostMaxFlow() {
            return minCostMaxFlow(Long.MAX_VALUE);
        }
        Pair<Long, Long> minCostMaxFlow(long maxf) {
            long flow = 0, cost = 0;
            while (flow < maxf) {
                Arrays.fill(dist, Long.MAX_VALUE);
                dist[s] = 0;
                PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
                pq.offer(new long[]{0, s});
                while (!pq.isEmpty()) {
                    long[] cur = pq.poll();
                    long d = cur[0];
                    int v = (int) cur[1];
                    if (dist[v] < d) continue;
                    for (int i = 0; i < g.adj[v].size(); i++) {
                        Edge e = g.adj[v].get(i);
                        if (e.cap > 0) {
                            long nd = d + e.cost + potential[v] - potential[e.to];
                            if (dist[e.to] > nd) {
                                dist[e.to] = nd;
                                prevv[e.to] = v;
                                preve[e.to] = i;
                                pq.offer(new long[]{nd, e.to});
                            }
                        }
                    }
                }
                if (dist[t] == Long.MAX_VALUE) break;
                for (int v = 0; v < g.V; v++) {
                    if (dist[v] < Long.MAX_VALUE) potential[v] += dist[v];
                }
                long add = maxf - flow;
                for (int v = t; v != s; v = prevv[v]) {
                    add = Math.min(add, g.adj[prevv[v]].get(preve[v]).cap);
                }
                flow += add;
                cost += add * potential[t];
                for (int v = t; v != s; v = prevv[v]) {
                    Edge e = g.adj[prevv[v]].get(preve[v]);
                    e.cap -= add;
                    e.rev.cap += add;
                }
            }
            return new Pair<>(cost, flow);
        }
    }

    static class Pair<U, V> {
        U first;
        V second;
        Pair(U first, V second) {
            this.first = first;
            this.second = second;
        }
    }
}
